#!/usr/bin/env python3
"""Create an offline interactive branded preview from the actual 2026 SVG assets."""
from pathlib import Path
import json, base64
root=Path(__file__).resolve().parents[1]
icons={p.stem:p.read_text().replace('#4743D5','currentColor') for p in (root/'brand/svg/tools').glob('*.svg')}
brand='data:image/png;base64,'+base64.b64encode((root/'brand/previews/jumlo-192.png').read_bytes()).decode()
mark='data:image/svg+xml;base64,'+base64.b64encode((root/'brand/svg/jumlo-symbol.svg').read_bytes()).decode()
template='''<!doctype html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1.0"/><title>Jumlo 2026 | Prism Identity Preview</title>
<style>
:root{--purple:#4946D5;--ink:#161F3C;--muted:#63708B;--canvas:#F6F7FD;--white:#fff;--line:#E6EAF5;--shadow:0 24px 70px #17204B1F}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 0 0,#F0EBFF 0,transparent 35%),#EFF2FA;color:var(--ink);font-family:Inter,"IBM Plex Sans",Arial,sans-serif}button{font:inherit;cursor:pointer;border:0}button:focus-visible{outline:3px solid #0D7F74;outline-offset:3px}.layout{max-width:1240px;min-height:100vh;margin:auto;display:grid;grid-template-columns:minmax(300px,1fr) 420px;align-items:center;gap:68px;padding:36px 28px}.left{padding:16px 0}.brandline{display:flex;align-items:center;gap:15px;font-weight:800;letter-spacing:.12em;font-size:13px}.brandline img{width:54px;height:54px;border-radius:16px}.eyebrow{color:#635DD9;font-size:12px;letter-spacing:.19em;font-weight:800;margin:52px 0 15px}.headline{font-size:clamp(45px,5vw,72px);line-height:1.065;letter-spacing:-.066em;margin:0;max-width:640px;font-weight:840}.headline span{color:#5953E9}.desc{color:#69728B;max-width:540px;font-size:18px;line-height:1.65;margin:25px 0 28px}.ctrl{display:flex;flex-wrap:wrap;gap:10px}.chip{border-radius:16px;background:#fff;color:#334260;padding:13px 17px;font-weight:700;box-shadow:0 3px 10px #1621420c}.chip.active{background:#4843CB;color:#fff}.footnote{color:#78839B;font-size:12px;line-height:1.7;margin-top:28px;max-width:560px}.signature{margin-top:35px;display:flex;gap:8px;flex-wrap:wrap}.signature small{padding:9px 13px;border-radius:30px;background:#E6E7FC;color:#5148B6;font-weight:700}.phone{border:9px solid #161C38;background:#161C38;padding:3px;border-radius:52px;box-shadow:0 32px 90px #1A21553D;max-width:420px;width:100%;margin:auto}.screen{height:810px;border-radius:40px;overflow:hidden;position:relative;background:var(--canvas);color:var(--ink);transition:background .25s,color .25s}.screen.dark{--canvas:#0C1226;--white:#171F39;--ink:#F1F3FF;--muted:#BBC5DE;--line:#394561;--purple:#A9B7FF}.camera{position:absolute;z-index:6;left:50%;transform:translateX(-50%);height:23px;width:96px;border-radius:17px;background:#141B35;top:10px}.status{height:48px;padding:21px 28px 0;display:flex;justify-content:space-between;font-size:12px;font-weight:800;position:relative;z-index:2}.inside{height:685px;overflow:auto;padding:17px 19px 108px;scrollbar-width:none}.inside::-webkit-scrollbar{display:none}.top{display:flex;align-items:center;justify-content:space-between;margin-bottom:21px}.name{display:flex;align-items:center;gap:10px;font-size:23px;font-weight:800;letter-spacing:-1px}.name img{width:43px;height:43px;border-radius:14px}.tinybtn{height:42px;width:42px;background:var(--white);border-radius:15px;color:var(--ink);display:grid;place-items:center}.icon{display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px}.icon svg{width:100%;height:100%}.kicker{font-size:13px;color:var(--muted);margin:0 0 18px}.search{background:var(--white);border-radius:18px;color:var(--muted);padding:14px 16px;display:flex;align-items:center;gap:11px;font-size:13px;margin-bottom:22px;box-shadow:0 2px 10px #19205406}.search .icon{width:20px}.sectionline{display:flex;align-items:center;justify-content:space-between;margin:20px 0 13px}.sectionline b{font-size:18px;letter-spacing:-.5px}.sectionline button{font-size:12px;color:var(--purple);font-weight:800;background:transparent}.hero{position:relative;isolation:isolate;border-radius:30px;padding:23px 23px 19px;color:#fff;background:linear-gradient(132deg,#323EC0,#8154C0);overflow:hidden;margin-bottom:20px;box-shadow:0 14px 25px #3436AF28}.hero::before{content:'';position:absolute;border-radius:50%;background:#ffffff13;width:210px;height:210px;right:-82px;top:-100px;z-index:-1}.hero-icon{height:51px;width:51px;border-radius:17px;background:#ffffff22;display:grid;place-items:center;margin-bottom:14px}.hero h2{font-size:25px;letter-spacing:-.9px;line-height:1.18;max-width:260px;margin:0}.hero p{max-width:270px;font-size:13px;line-height:1.6;color:#EAECFF;margin:8px 0 16px}.hero button{background:white;border-radius:17px;min-height:47px;width:100%;padding:11px 13px;font-weight:800;color:#3639AA;display:flex;gap:8px;justify-content:center;align-items:center}.tool-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px;margin-bottom:21px}.tool{background:var(--white);min-height:131px;border-radius:24px;display:flex;align-items:center;justify-content:center;gap:10px;flex-direction:column;padding:12px 8px;color:var(--ink);text-align:center;box-shadow:0 3px 10px #1D265013;transition:transform .2s}.tool:hover{transform:translateY(-2px)}.tileicon{display:grid;place-items:center;border-radius:19px;height:56px;width:56px;background:#E4E9FF;color:#384CCB}.tileicon .icon{height:28px;width:28px}.tileicon.teal{background:#DDF6F1;color:#087A73}.tileicon.coral{background:#FFE9EE;color:#B63557}.tileicon.violet{background:#F0E8FC;color:#7150A9}.tileicon.amber{background:#FFF2DF;color:#A46725}.tool strong{max-width:100%;line-height:1.25;font-weight:750;font-size:13px}.filecard{border-radius:19px;background:var(--white);display:flex;align-items:center;gap:12px;padding:11px;margin:8px 0;box-shadow:0 3px 10px #1D26500C}.fileico{width:43px;height:43px;border-radius:13px;background:#E7E9FF;color:#4C4CCB;display:grid;place-items:center}.fileinfo{min-width:0;flex:1}.fileinfo b{font-size:12px;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.fileinfo small{color:var(--muted);font-size:11px;display:block;margin-top:5px}.filters{display:flex;gap:7px;overflow:auto;margin:0 0 20px;scrollbar-width:none}.filter{white-space:nowrap;padding:10px 16px;border-radius:15px;background:var(--white);color:var(--muted);font-size:12px;font-weight:750}.filter.selected{background:#E4E8FF;color:#4641BA}.settings-row{width:100%;border-radius:21px;background:var(--white);display:flex;text-align:left;align-items:center;gap:12px;padding:15px;margin:9px 0;color:var(--ink)}.settings-row .tileicon{height:43px;width:43px;border-radius:13px}.settings-row .tileicon .icon{height:22px;width:22px}.settings-row b{font-size:13px}.settings-row small{display:block;font-size:11px;color:var(--muted);margin-top:5px}.dock{position:absolute;bottom:15px;left:11px;right:11px;z-index:4;height:77px;background:var(--white);border-radius:30px;box-shadow:0 8px 29px #11153125;display:flex;justify-content:space-between;align-items:center;padding:5px}.nav{background:none;color:var(--muted);border-radius:17px;display:flex;align-items:center;flex-direction:column;justify-content:center;gap:4px;min-width:0;flex:1;height:54px;font-size:11px;font-weight:700}.nav.active{background:#E5E9FF;color:#3D4CC7}.dark .nav.active{background:#29376E;color:#A9B7FF}.nav .icon{width:24px;height:24px}.nav.primary{color:white;height:64px;flex:0 0 61px;margin:-11px 2px 0;background:linear-gradient(130deg,#363EC0,#7658E4);border-radius:21px;box-shadow:0 8px 17px #473DB352}.nav.primary .icon{height:29px;width:29px}.splash{position:absolute;z-index:10;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;color:#fff;background:radial-gradient(circle at 100% 0,#5246B9 0,transparent 53%),linear-gradient(130deg,#0C1231,#29216F,#4535A9);transition:opacity .22s ease,visibility .22s ease}.splash.hidden{opacity:0;visibility:hidden;pointer-events:none}.orbit{position:absolute;height:282px;width:282px;border-radius:50%;border:1px solid #ffffff14;animation:orbit 5.2s linear infinite}.orbit:after{content:'';position:absolute;height:9px;width:9px;border-radius:50%;background:#84F8D5;top:-5px;left:50%}.splashlogo{position:relative;width:129px;height:129px;border-radius:38px;background:linear-gradient(120deg,#6250EA,#9170F5);display:grid;place-items:center;box-shadow:0 24px 60px #050D4420;animation:logo 0.64s cubic-bezier(.2,.9,.23,1.2) both}.splashlogo img{width:95px;height:95px;object-fit:contain}.word{font-size:43px;font-weight:800;letter-spacing:-2px;margin:24px 0 7px;animation:rise .55s .1s both}.word:after{content:'';display:inline-block;width:8px;height:8px;margin-left:3px;background:#83F5D2;border-radius:50%}.tag{font-size:14px;color:#E0E5FF;font-weight:500;animation:rise .6s .14s both}.previewnote{font-size:12px;color:var(--muted);text-align:center;margin:16px 0}@keyframes orbit{to{transform:rotate(360deg)}}@keyframes logo{from{transform:scale(.7);opacity:0}to{transform:scale(1);opacity:1}}@keyframes rise{from{transform:translateY(20px);opacity:0}to{transform:translateY(0);opacity:1}}@media(max-width:850px){.layout{grid-template-columns:1fr;gap:25px;padding:35px 18px}.left{max-width:600px;margin:auto}.eyebrow{margin-top:26px}.headline{font-size:45px}.phone{max-width:405px}.desc{font-size:16px}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
</style></head><body><main class="layout"><section class="left"><div class="brandline"><img src="__BRAND__" alt="Jumlo mark"/> JUMLO / 2026 DESIGN SYSTEM</div><p class="eyebrow">BORDERLESS · ROUNDED VECTOR ICONS · MOTION</p><h1 class="headline">Cleaner tools.<br/><span>A bolder Jumlo.</span></h1><p class="desc">A new folded-J identity, a softer borderless tool grid, and an elegant animated start screen. Built as real Jetpack Compose changes and vector assets in the source ZIP.</p><div class="ctrl"><button class="chip active" id="light" onclick="theme(false)">Light</button><button class="chip" id="dark" onclick="theme(true)">Dark</button><button class="chip" onclick="replay()">↻ Replay startup</button><button class="chip" onclick="go('tools')">Explore tools</button></div><div class="signature"><small>38 original vector icons</small><small>Light / Dark</small><small>Adaptive launcher</small><small>Reduced-motion support</small></div><p class="footnote">Visual prototype only: the actual tool workflows stay in the Android source. Android device behavior and APK building require on-device/CI verification. The displayed filenames are examples, not real user files.</p></section><div class="phone"><div class="screen" id="screen"><div class="camera"></div><div class="status"><span>9:41</span><span>◕ ◕ ▰</span></div><div class="inside" id="content"></div><div class="dock" id="dock"></div><div class="splash" id="splash"><div class="orbit"></div><div class="splashlogo"><img src="__MARK__" alt=""/></div><div class="word">Jumlo</div><div class="tag">Create. Scan. Make it flow.</div></div></div></div></main>
<script>
const GLYPHS=__GLYPHS__;let page='home',isDark=false;
const screen=document.getElementById('screen'),content=document.getElementById('content'),dock=document.getElementById('dock'),splash=document.getElementById('splash');
const icon=(name,cls='')=>'<span class="icon '+cls+'">'+(GLYPHS[name]||GLYPHS.sparkles)+'</span>';
const tile=(name,label,cls='')=>`<button class="tool" type="button" onclick="tip()"><span class="tileicon ${cls}">${icon(name)}</span><strong>${label}</strong></button>`;
const head=()=>`<div class="top"><div class="name"><img src="__BRAND__" alt=""/>Jumlo</div><button class="tinybtn" onclick="go('settings')" aria-label="Settings">${icon('settings')}</button></div>`;
const file=(label,details,ico='document')=>`<div class="filecard"><div class="fileico">${icon(ico)}</div><div class="fileinfo"><b>${label}</b><small>${details}</small></div></div>`;
const title=t=>`<div class="sectionline"><b>${t}</b><button onclick="go('tools')">See all →</button></div>`;
const pages={
 home:()=>`${head()}<p class="kicker">Your files, your workspace.</p><div class="search">${icon('search')}Search files and tools</div><div class="hero"><div class="hero-icon">${icon('scan')}</div><h2>Scan beautifully.<br/>In a tap.</h2><p>Capture, enhance and turn documents into PDFs.</p><button onclick="go('scan')">${icon('scan')} Open scanner <span>↗</span></button></div>${title('Quick actions')}<div class="tool-grid">${tile('document','Edit PDF')}${tile('compress','Compress PDF','violet')}${tile('merge','Merge PDF','teal')}${tile('image','Image to PDF','coral')}</div>${title('Recent files')}${file('Project overview.pdf','Example document · 1.8 MB')}`,
 tools:()=>`${head()}<h2 style="font-size:26px;letter-spacing:-.9px;margin:7px 0 16px">All your tools.</h2><div class="search">${icon('search')}Search a document tool</div><div class="filters"><button class="filter selected">All</button><button class="filter">PDF</button><button class="filter">Images</button><button class="filter">Files</button><button class="filter">Downloads</button></div>${title('PDF essentials')}<div class="tool-grid">${tile('document','View PDF')}${tile('compress','Compress PDF','violet')}${tile('merge','Merge PDF','teal')}${tile('split','Split PDF','coral')}${tile('edit','Annotate PDF')}${tile('lock','Protect PDF','amber')}</div>${title('Scans & images')}<div class="tool-grid">${tile('scan','Document Scan','teal')}${tile('image','Images to PDF')}${tile('crop','Crop & Rotate','coral')}${tile('ocr','OCR Text','violet')}</div>`,
 files:()=>`${head()}<h2 style="font-size:25px">Files.</h2><div class="search">${icon('search')}Find a saved file</div>${title('Recent files')}${file('Project overview.pdf','Example · Today · 1.8 MB')}${file('Business cards.pdf','Example · Yesterday · 3.2 MB')}${file('Receipt.png','Example · Tuesday · 648 KB','image')}${title('Quick management')}<div class="tool-grid">${tile('archive','Create ZIP','violet')}${tile('unarchive','Extract ZIP','teal')}</div>`,
 downloads:()=>`${head()}<h2 style="font-size:25px">Downloads.</h2><p class="kicker">Manage your transfers with clarity.</p><div class="filecard"><div class="fileico">${icon('download')}</div><div class="fileinfo"><b>No active transfers</b><small>Waiting for a new direct download</small></div></div>${title('Download actions')}<div class="tool-grid">${tile('link','Direct link')}${tile('cloud','Cloud file','teal')}</div>`,
 settings:()=>`${head()}<h2 style="font-size:25px">Make Jumlo yours.</h2>${title('Appearance')}<button class="settings-row" onclick="theme(!isDark)"><div class="tileicon violet">${icon('settings')}</div><div><b>App theme</b><small>Tap to switch light and dark</small></div></button><button class="settings-row" onclick="tip()"><div class="tileicon">${icon('sparkles')}</div><div><b>Accent color</b><small>Indigo, teal, coral, violet, dynamic</small></div></button><button class="settings-row" onclick="tip()"><div class="tileicon teal">${icon('globe')}</div><div><b>Language</b><small>English / Arabic</small></div></button>${title('Experience')}<button class="settings-row" onclick="tip()"><div class="tileicon violet">${icon('eye')}</div><div><b>Motion & accessibility</b><small>Large labels and reduced animation</small></div></button>`,
 scan:()=>`${head()}<h2 style="font-size:25px">Scan documents.</h2><div style="height:395px;border-radius:25px;background:linear-gradient(155deg,#263754,#10182D);display:grid;place-items:center;color:white"><div style="width:73%;height:68%;border:3px solid #7CECD2;border-radius:16px;display:grid;place-items:center;text-align:center;padding:20px">${icon('scan')}<small>Camera preview appears in the Android app</small></div></div><p class="previewnote">Guide-only illustration. The real scanner uses CameraX.</p><button class="chip active" style="width:100%" onclick="go('home')">Back to home</button>`};
function go(p){page=p;content.innerHTML=pages[p]();dock.innerHTML=[['home','home','Home'],['tools','grid','Tools'],['scan','scan','Scan'],['files','folder','Files'],['downloads','download','Downloads']].map(([id,img,txt])=>`<button class="nav ${p===id?'active':''} ${id==='scan'?'primary':''}" onclick="go('${id}')" aria-label="${txt}">${icon(img)}${id==='scan'?'':txt}</button>`).join('')}
function theme(flag){isDark=flag;screen.classList.toggle('dark',flag);document.getElementById('dark').classList.toggle('active',flag);document.getElementById('light').classList.toggle('active',!flag);go(page)}
let playback;function replay(){clearTimeout(playback);splash.classList.remove('hidden');const tag=splash.querySelector('.splashlogo');tag.style.animation='none';void tag.offsetWidth;tag.style.animation='';playback=setTimeout(()=>splash.classList.add('hidden'),1150)}
let noteTimer;function tip(){const old=document.getElementById('notice');if(old)old.remove();const m=document.createElement('div');m.id='notice';m.textContent='This preview is visual; the real action is in the Android app.';m.style='position:absolute;z-index:8;bottom:106px;left:22px;right:22px;background:#20284B;color:white;font-size:12px;line-height:1.4;padding:15px;border-radius:16px;box-shadow:0 9px 20px #0002';screen.appendChild(m);clearTimeout(noteTimer);noteTimer=setTimeout(()=>m.remove(),2500)}
go('home');replay();
</script></body></html>'''
rendered=template.replace('__GLYPHS__',json.dumps(icons,ensure_ascii=True)).replace('__BRAND__',brand).replace('__MARK__',mark)
(root/'design/Jumlo-Prism-2026-Preview.html').write_text(rendered,encoding='utf-8')
print('Preview created',len(rendered),'bytes')
